mapper.select:
select plan.learningPlanID,plan.name,plan.partyCode,plan.learningPlanType,plan.publicDate,plan.request
,plan.content,plan.recordStatus,plan.createTime,plan.createUserId,plan.createUserName,plan.updateTime,plan.updateUserId,plan.updateUserName
,dicType.DICVALUE as learningPlanTypeName,dicStatus.DICVALUE as recordStatusName,p.DZZMC as partyName
from zz_learningplan plan
left join cf_dictionary dicType on plan.learningPlanType = dicType.DICKEY and dicType.DICTYPEKEY='LearningPlanType'
left join cf_dictionary dicStatus on plan.recordStatus = dicStatus.DICKEY and dicStatus.DICTYPEKEY='LearningPlanPublicStatus'
left join zz_zzqkxx p on plan.partyCode = p.DZZDM


        and plan.learningPlanID = #{planID}


        and plan.name like concat('%',#{planName},'%')


        and plan.publicDate >= #{startDate}


        and plan.publicDate <= #{endDate}


        and plan.recordStatus = #{recordStatus}


        and plan.learningPlanType = #{learningPlanType}


order by plan.publicDate desc
